INSERT INTO notices (title, content, date_posted, target_audience) VALUES
('Hostel Room Allocation Commencement - Academic Year 2025/2026', 'All 160 eligible undergraduate students across Blocks A and B are requested to complete room check-in with the Sub Warden office on or before June 5th, 2026.', '2026-06-01', 'ALL'),
('Notice on Timely Monthly Hostel Fee Settlement', 'Students are reminded that the monthly accommodation fee of Rs. 1,500.00 must be remitted prior to the 10th of each calendar month. Official digital receipts are automatically generated.', '2026-07-01', 'STUDENTS'),
('Annual Fire Safety & Electrical Equipment Audit', 'The University Safety Directorate and Facility Maintenance Team will perform inspection of all electrical points, DB boxes, and fire extinguishers in Blocks A, B, C, D on August 15th.', '2026-08-10', 'ALL'),
('Semester Examination Curfew & Study Environment Guidelines', 'Silent study hours will be strictly enforced between 09:00 PM and 06:00 AM during the upcoming mid-semester assessment period. Gate passes will only be granted for verified emergencies.', '2026-09-15', 'ALL'),
('Hostel Accommodation Fee Collection - October 2026', 'All resident students living in Blocks A and B are requested to settle their monthly accommodation fee of Rs. 1,500.00 on or before October 31st, 2026 via the online portal.', '2026-10-01', 'STUDENTS'),
('Scheduled Main Overhead Water Reservoir Chlorination', 'Please be notified that the main water reservoir will undergo routine descaling and chlorinated disinfection on Thursday, October 29th, from 09:00 AM to 03:00 PM. Water supply will be temporarily paused.', '2026-10-22', 'ALL');
