-- ============================================================================
-- Advance Database Management Systems (ADBMS) - Comprehensive Master Dataset
-- University of Ruhuna - Faculty of Technology - Hostel Management System (HMS)
-- 100 Rooms (Blocks A, B, C, D - 25 rooms each) | 160 Resident Students
-- 15 Department Staff (Security, Maintenance, Cleaning) | 2,000+ Shifts (June - Oct 2026)
-- 800+ Monthly Payments | 35+ Maintenance Work Orders | 30+ Gate Passes
-- Zero ORM Architecture - Pure Relational SQL Seeding Script
-- Current System Date Reference: 2026-10-27
-- ============================================================================

SET NAMES utf8mb4;
USE hms_db;

SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------------------------------------------------------
-- 1. HOSTEL ROOMS (100 Rooms: Blocks A, B, C, D - 25 Rooms per Block/Floor)
-- Capacity: 4 beds per room. Total Capacity: 400 beds.
-- 160 Students allocated systematically into the first 40 rooms (4 beds filled each).
-- Block A: Rooms 1-25 (all 25 full, 100 students)
-- Block B: Rooms 26-40 (15 full, 60 students), Rooms 41-50 (vacant)
-- Block C: Rooms 51-75 (vacant, ready for new admissions)
-- Block D: Rooms 76-100 (vacant, ready for new admissions)
-- ----------------------------------------------------------------------------
DELETE FROM rooms;


-- ----------------------------------------------------------------------------
-- 2. USERS DIRECTORY (Admin, 15 Department Staff, 160 Resident Students)
-- Security Staff: SEC001 - SEC004 (4 Officers)
-- Maintenance Staff: MNT001 - MNT005 (5 Specialists)
-- Cleaning Staff: CLN001 - CLN006 (6 Housekeeping Staff)
-- Resident Students: TG/2021/0001 - TG/2021/0160 (160 Students)
-- ----------------------------------------------------------------------------
DELETE FROM users;


-- ----------------------------------------------------------------------------
-- 3. INVENTORY CATALOG (Central Logistics Master Warehouse Stock)
-- ----------------------------------------------------------------------------
DELETE FROM inventory;


-- ----------------------------------------------------------------------------
-- 4. STAFF ATTENDANCE HISTORY (From 2026-06-01 to 2026-10-27: ~2,000 Shifts)
-- Covers Security (SEC001-004), Maintenance (MNT001-005), Cleaning (CLN001-006)
-- ----------------------------------------------------------------------------
DELETE FROM staff_attendance;


-- ----------------------------------------------------------------------------
-- 5. MONTHLY ACCOMMODATION FEES (June, July, August, September, October 2026)
-- 160 resident students x 5 billing months = 800 invoice records.
-- June, July, August, September: 100% Settled (Rs. 1,500.00 each)
-- October: 140 Settled, 20 Pending (Arrears testing)
-- ----------------------------------------------------------------------------
DELETE FROM payments;


-- ----------------------------------------------------------------------------
-- 6. MAINTENANCE COMPLAINTS & WORK ORDERS (35 Comprehensive Incidents)
-- Across Blocks A, B, C, D (June - October 2026)
-- ----------------------------------------------------------------------------
DELETE FROM complaints;


-- ----------------------------------------------------------------------------
-- 7. STUDENT GATE PASSES & CAMPUS LEAVE (30 Comprehensive Records)
-- Returned, Departed, Pending, and Rejected passes (June - October 2026)
-- ----------------------------------------------------------------------------
DELETE FROM gate_passes;


-- ----------------------------------------------------------------------------
-- 8. ROOM INVENTORY DAMAGES & ASSET REPAIR TRACKER
-- ----------------------------------------------------------------------------
DELETE FROM room_inventory;


-- ----------------------------------------------------------------------------
-- 9. OFFICIAL BULLETIN NOTICES (Administrative Circulars June - October 2026)
-- ----------------------------------------------------------------------------
DELETE FROM notices;


-- ----------------------------------------------------------------------------
-- 10. SYSTEM AUDIT TRAILS (User Room Allocations & Payment Transactions)
-- ----------------------------------------------------------------------------
DELETE FROM user_audit_log;


DELETE FROM payment_audit_log;


-- ----------------------------------------------------------------------------
-- 11. HOSTEL OCCUPANCY DAILY STATS (Snapshots across Blocks)
-- ----------------------------------------------------------------------------
DELETE FROM hostel_daily_stats;


SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================================
-- Verification Summary Queries
-- ============================================================================
SELECT 'MASSIVE DATASET INSERTION COMPLETE' AS Status;
SELECT COUNT(*) AS total_rooms FROM rooms;
SELECT block_name, COUNT(*) AS rooms_count, SUM(current_occupancy) AS total_occupied_students FROM rooms GROUP BY block_name;
SELECT role, COUNT(*) AS count_by_role FROM users GROUP BY role;
SELECT COUNT(*) AS total_attendance_shifts FROM staff_attendance;
SELECT month, status, COUNT(*) AS count, SUM(amount) AS total_lkr FROM payments GROUP BY month, status ORDER BY MIN(payment_date);
SELECT status, COUNT(*) AS complaints_count FROM complaints GROUP BY status;
SELECT status, COUNT(*) AS gatepasses_count FROM gate_passes GROUP BY status;
